mapper.select:
select
task_info.*
,task_type.name as taskTypeName
,rcs_car.name as rcsCarName

from task_info task_info
left join task_type task_type on task_info.type = task_type.code and task_type.ware_code = task_info.ware_code
left join rcs_car_info rcs_car on task_info.rcs_car_id = rcs_car.id

     and task_info.task_no like concat('%',#{taskNo},'%')
     and task_info.id = #{id}
     and task_info.wms_task_no = #{wmsTaskNo}
     and task_info.ware_code = #{wareCode}
     and task_info.ware_name like concat('%', #{wareName}, '%')
     and task_info.area_code = #{areaCode}
     and task_info.area_name like concat('%', #{areaName}, '%')
     and task_info.type = #{type}
     and task_info.pallet_code = #{palletCode}
     and task_info.from_cell_code = #{fromCellCode}
     and task_info.to_cell_code = #{toCellCode}
     and task_info.state = #{state}
     and task_info.rcs_car_id = #{rcsCarId}
     and task_info.create_time >= #{params.createTimeStart}
     and task_info.create_time <= #{params.createTimeEnd}
     and task_info.finish_time >= #{params.finishTimeStart}
     and task_info.finish_time <= #{params.finishTimeEnd}

order by task_info.priority desc

select * from task_info
where state = #{state}
and ware_code = #{wareCode}
order by priority desc

mapper.insert:
insert into task_info_history select * from task_info where id = #{taskId};
insert into job_info_history select * from job_info where task_id = #{taskId};
insert into job_handle_history select * from job_handle where task_id = #{taskId};



delete from task_info  where id = #{taskId};
delete from job_info  where task_id = #{taskId};
delete from job_handle  where task_id = #{taskId};

mapper.update:
update task_info
task_no = #{taskNo}, wms_task_no = #{wmsTaskNo}, ware_code = #{wareCode}, ware_name = #{wareName}, area_code = #{areaCode}, area_name = #{areaName}, type = #{type}, pallet_code = #{palletCode}, from_cell_code = #{fromCellCode}, to_cell_code = #{toCellCode}, create_time = #{createTime}, state = #{state}, version = #{version}, remark1 = #{remark1}, remark2 = #{remark2}, remark3 = #{remark3}, pallet_type = #{palletType}, rcs_car_id = #{rcsCarId},
where id = #{id}
